import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Inline CUDA extension implementing fp16 tanh
_cpp_sources = r'''
#include <torch/extension.h>
'''

_cuda_sources = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void tanh_fp16_kernel(const __half* __restrict__ input,
                                 __half* __restrict__ output,
                                 int64_t N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    for (int i = idx; i < N; i += stride) {
        __half val = input[i];
        float f = __half2float(val);
        float tanh_f = tanhf(f);
        output[i] = __float2half(tanh_f);
    }
}

void tanh_fp16_forward(at::Tensor input, at::Tensor output) {
    const __half* in = reinterpret_cast<const __half*>(input.data_ptr<at::Half>());
    __half* out = reinterpret_cast<__half*>(output.data_ptr<at::Half>());
    int64_t N = input.numel();
    const int threads = 256;
    const int blocks = (N + threads - 1) / threads;
    tanh_fp16_kernel<<<blocks, threads, 0, at::cuda::getCurrentCUDAStream()>>>(in, out, N);
}
'''

# Compile the extension
_tanh_fp16 = load_inline(
    name="tanh_fp16",
    cpp_sources=_cpp_sources,
    cuda_sources=_cuda_sources,
    functions=["tanh_fp16_forward"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Model that applies a Tanh activation using a custom fp16 CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is fp16 and contiguous
        x = x.to(torch.float16)
        if not x.is_contiguous():
            x = x.contiguous()
        # Prepare output tensor
        out = torch.empty_like(x, dtype=torch.float16, device=x.device)
        # Launch custom kernel
        _tanh_fp16.tanh_fp16_forward(x, out)
        return out

# Helper functions matching the reference API
batch_size = 4096
dim = 393216

def get_inputs():
    x = torch.rand(batch_size, dim, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    return []  # No special initialization inputs needed
